describe('Drawer/Slide-in Panel from Right', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should open drawer/slide-in panel from right with correct animation and visibility', () => {
    // Verify drawer is closed by default
    cy.get('[data-testid="drawer-panel"]').should('not.be.visible');

    // Click the drawer toggle button
    cy.get('[data-testid="drawer-toggle-button"]').click();

    // Verify drawer is now visible and sliding in from the right
    cy.get('[data-testid="drawer-panel"]').should('be.visible');
    cy.get('[data-testid="drawer-panel"]').should('have.css', 'transform', 'translateX(-100%)');

    // Verify drawer content is accessible
    cy.get('[data-testid="drawer-content"]').should('be.visible');
    cy.get('[data-testid="drawer-content"]').should('contain', 'Drawer content');

    // Verify drawer has correct animation
    cy.get('[data-testid="drawer-panel"]').should('have.css', 'transition', 'transform 0.3s ease');

    // Verify close button is visible
    cy.get('[data-testid="drawer-close-button"]').should('be.visible');

    // Verify close button works
    cy.get('[data-testid="drawer-close-button"]').click();

    // Verify drawer is closed
    cy.get('[data-testid="drawer-panel"]').should('not.be.visible');
    cy.get('[data-testid="drawer-panel"]').should('have.css', 'transform', 'translateX(0%)');
  });

  it('should handle drawer overflow and prevent content from being cut off', () => {
    // Open drawer
    cy.get('[data-testid="drawer-toggle-button"]').click();
    cy.get('[data-testid="drawer-panel"]').should('be.visible');

    // Verify drawer content is fully visible
    cy.get('[data-testid="drawer-content"]').should('be.visible');

    // Verify drawer content does not overflow
    cy.get('[data-testid="drawer-content"]').should('have.css', 'overflow-y', 'scroll');

    // Verify scrollbar appears when content is too long
    cy.get('[data-testid="drawer-content"]').should('have.css', 'overflow-y', 'scroll');

    // Verify scrollbar is functional
    cy.get('[data-testid="drawer-content"]').scrollTo('bottom');
    cy.get('[data-testid="drawer-content"]').should('be.visible');

    // Verify drawer closes when scrollbar is used
    cy.get('[data-testid="drawer-close-button"]').click();

    // Verify drawer is closed
    cy.get('[data-testid="drawer-panel"]').should('not.be.visible');
  });
});
